-- Module 20: configurable generic Job Orders with atomic material consumption.
update public.module_definitions set configuration_schema='{"properties":{"singular_label":{"type":"string","label":"Singular label","maxLength":40,"default":"Job Order"},"plural_label":{"type":"string","label":"Plural label","maxLength":50,"default":"Job Orders"},"consume_inventory":{"type":"boolean","label":"Consume material inventory","default":true},"consumption_trigger":{"type":"enum","label":"Inventory consumption trigger","options":["manual","on_start","on_complete"],"default":"manual"}},"additionalProperties":false}'::jsonb,updated_at=now()where key='job_orders';
insert into public.permissions(key,domain,action,description)values
 ('job-orders.read','job_orders','read','View job orders and work history'),('job-orders.manage','job_orders','manage','Create and manage job orders'),
 ('job-orders.status','job_orders','status','Advance job order status'),('job-orders.materials','job_orders','materials','Consume job order materials from inventory')
on conflict(key)do update set domain=excluded.domain,action=excluded.action,description=excluded.description;
create function private.install_job_order_permissions(requested_organization_id uuid)returns void language plpgsql security definer set search_path='' as $$begin
 insert into public.role_permissions(role_id,permission_id)select role.id,permission.id from public.roles role cross join public.permissions permission where role.organization_id=requested_organization_id and role.key in('owner','administrator','manager')and permission.key like'job-orders.%'on conflict do nothing;
 insert into public.role_permissions(role_id,permission_id)select role.id,permission.id from public.roles role join public.permissions permission on permission.key=any(case role.key when'staff'then array['job-orders.read','job-orders.status','job-orders.materials']when'viewer'then array['job-orders.read']else array[]::text[]end)where role.organization_id=requested_organization_id and role.key in('staff','viewer')on conflict do nothing;
end;$$;
create function private.handle_main_branch_job_order_permissions()returns trigger language plpgsql security definer set search_path='' as $$begin if new.code='main'then perform private.install_job_order_permissions(new.organization_id);end if;return new;end;$$;
create trigger zzzzzzz_install_job_order_permissions_on_main_branch after insert on public.branches for each row execute function private.handle_main_branch_job_order_permissions();select private.install_job_order_permissions(id)from public.organizations;

create table public.job_order_staff(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id)on delete cascade,membership_id uuid not null,user_id uuid not null references auth.users(id)on delete restrict,display_name text not null check(char_length(btrim(display_name))between 1 and 160),status text not null default'active'check(status in('active','inactive')),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(id,organization_id),unique(organization_id,membership_id),unique(organization_id,user_id),foreign key(membership_id,organization_id)references public.organization_memberships(id,organization_id)on delete cascade);
create table public.job_order_counters(organization_id uuid primary key references public.organizations(id)on delete cascade,next_value bigint not null default 1 check(next_value>0));
create table public.job_orders(
 id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id)on delete cascade,branch_id uuid not null,job_number text not null,
 customer_id uuid not null,assigned_staff_id uuid,service_id uuid,service_type text not null check(char_length(btrim(service_type))between 1 and 160),description text not null check(char_length(btrim(description))between 1 and 4000),
 status text not null default'new'check(status in('new','accepted','in_progress','waiting','completed','released','cancelled')),priority text not null default'normal'check(priority in('low','normal','high','urgent')),
 start_date date,due_date date,completed_date date,labor_total numeric(16,4)not null default 0 check(labor_total>=0),material_total numeric(16,4)not null default 0 check(material_total>=0),notes text check(char_length(notes)<=4000),
 created_by uuid not null references auth.users(id),updated_by uuid not null references auth.users(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(id,organization_id),unique(organization_id,job_number),
 foreign key(branch_id,organization_id)references public.branches(id,organization_id)on delete restrict,foreign key(customer_id,organization_id)references public.sales_customers(id,organization_id)on delete restrict,
 foreign key(assigned_staff_id,organization_id)references public.job_order_staff(id,organization_id)on delete restrict,foreign key(service_id,organization_id)references public.products(id,organization_id)on delete restrict,
 check(due_date is null or start_date is null or due_date>=start_date)
);
create table public.job_order_labor_items(id uuid primary key default gen_random_uuid(),organization_id uuid not null,job_order_id uuid not null,description text not null check(char_length(btrim(description))between 1 and 500),hours numeric(10,4)not null check(hours>0),hourly_rate numeric(16,4)not null check(hourly_rate>=0),amount numeric(16,4)not null check(amount>=0),position integer not null check(position>=0),unique(job_order_id,position),foreign key(job_order_id,organization_id)references public.job_orders(id,organization_id)on delete cascade);
create table public.job_order_material_items(id uuid primary key default gen_random_uuid(),organization_id uuid not null,job_order_id uuid not null,product_variant_id uuid not null,inventory_item_id uuid not null,inventory_location_id uuid not null,description text not null check(char_length(btrim(description))between 1 and 500),planned_quantity numeric(16,4)not null check(planned_quantity>0),consumed_quantity numeric(16,4)not null default 0 check(consumed_quantity>=0 and consumed_quantity<=planned_quantity),unit_cost numeric(16,4)not null check(unit_cost>=0),amount numeric(16,4)not null check(amount>=0),position integer not null check(position>=0),unique(job_order_id,position),foreign key(job_order_id,organization_id)references public.job_orders(id,organization_id)on delete cascade,foreign key(product_variant_id,organization_id)references public.product_variants(id,organization_id)on delete restrict,foreign key(inventory_item_id,organization_id)references public.inventory_items(id,organization_id)on delete restrict,foreign key(inventory_location_id,organization_id)references public.inventory_locations(id,organization_id)on delete restrict);
create table public.job_order_attachments(id uuid primary key default gen_random_uuid(),organization_id uuid not null,job_order_id uuid not null,path text not null,file_name text not null check(char_length(file_name)between 1 and 255),mime_type text not null,size_bytes bigint not null check(size_bytes between 1 and 10485760),uploaded_by uuid not null references auth.users(id),created_at timestamptz not null default now(),unique(organization_id,path),foreign key(job_order_id,organization_id)references public.job_orders(id,organization_id)on delete cascade);
create table public.job_order_audit_history(id uuid primary key default gen_random_uuid(),organization_id uuid not null,job_order_id uuid not null,event text not null,from_status text,to_status text,actor_id uuid not null references auth.users(id),details jsonb not null default'{}',created_at timestamptz not null default now(),foreign key(job_order_id,organization_id)references public.job_orders(id,organization_id)on delete cascade);
create index job_order_staff_active_idx on public.job_order_staff(organization_id,status,display_name);create index job_orders_queue_idx on public.job_orders(organization_id,branch_id,status,priority,due_date);create index job_orders_customer_idx on public.job_orders(customer_id,created_at desc);create index job_orders_staff_idx on public.job_orders(assigned_staff_id,status,due_date)where assigned_staff_id is not null;create index job_labor_order_idx on public.job_order_labor_items(job_order_id,position);create index job_material_order_idx on public.job_order_material_items(job_order_id,position);create index job_material_inventory_idx on public.job_order_material_items(inventory_item_id,inventory_location_id);create index job_attachments_order_idx on public.job_order_attachments(job_order_id,created_at);create index job_audit_order_idx on public.job_order_audit_history(job_order_id,created_at desc);
create trigger set_updated_at before update on public.job_order_staff for each row execute function private.set_updated_at();create trigger set_updated_at before update on public.job_orders for each row execute function private.set_updated_at();
insert into public.job_order_staff(organization_id,membership_id,user_id,display_name)select membership.organization_id,membership.id,membership.user_id,coalesce(nullif(btrim(profile.display_name),''),split_part(user_record.email,'@',1),'Staff')from public.organization_memberships membership join auth.users user_record on user_record.id=membership.user_id left join public.profiles profile on profile.id=membership.user_id where membership.status='active'on conflict(organization_id,membership_id)do nothing;
create function private.sync_job_order_staff_membership()returns trigger language plpgsql security definer set search_path='' as $$declare name_value text;begin select coalesce(nullif(btrim(profile.display_name),''),split_part(user_record.email,'@',1),'Staff')into name_value from auth.users user_record left join public.profiles profile on profile.id=user_record.id where user_record.id=new.user_id;insert into public.job_order_staff(organization_id,membership_id,user_id,display_name,status)values(new.organization_id,new.id,new.user_id,name_value,case when new.status='active'then'active'else'inactive'end)on conflict(organization_id,membership_id)do update set display_name=excluded.display_name,status=excluded.status;return new;end;$$;create trigger sync_job_order_staff after insert or update of status on public.organization_memberships for each row execute function private.sync_job_order_staff_membership();

create function private.job_orders_module_enabled(requested_organization_id uuid)returns boolean language sql stable security definer set search_path='' as $$select exists(select 1 from public.organization_modules module join public.module_definitions definition on definition.id=module.module_id where module.organization_id=requested_organization_id and module.is_enabled and definition.key='job_orders');$$;
create function private.job_order_config(requested_organization_id uuid)returns jsonb language sql stable security definer set search_path='' as $$select coalesce(module.config,'{}')from public.organization_modules module join public.module_definitions definition on definition.id=module.module_id where module.organization_id=requested_organization_id and module.is_enabled and definition.key='job_orders';$$;
create function private.next_job_number(requested_organization_id uuid)returns text language plpgsql security definer set search_path='' as $$declare value bigint;begin insert into public.job_order_counters(organization_id,next_value)values(requested_organization_id,2)on conflict(organization_id)do update set next_value=public.job_order_counters.next_value+1 returning next_value-1 into value;if value is null then value:=1;end if;return'JOB-'||extract(year from current_date)::integer||'-'||lpad(value::text,6,'0');end;$$;
create function private.can_read_job_order(requested_organization_id uuid,requested_job_order_id uuid)returns boolean language sql stable security definer set search_path='' as $$select private.job_orders_module_enabled(requested_organization_id)and exists(select 1 from public.job_orders job where job.id=requested_job_order_id and job.organization_id=requested_organization_id and private.can_business_permission(requested_organization_id,'job-orders.read',job.branch_id));$$;

create function private.save_job_order(requested_organization_id uuid,requested_branch_id uuid,requested_customer_id uuid,requested_staff_id uuid,requested_service_id uuid,requested_service_type text,requested_description text,requested_priority text,requested_start_date date,requested_due_date date,requested_notes text,requested_labor_items jsonb,requested_material_items jsonb)returns uuid language plpgsql security definer set search_path='' as $$
declare actor uuid:=(select auth.uid());target_id uuid:=gen_random_uuid();number text;item jsonb;position_value integer:=0;labor_sum numeric:=0;material_sum numeric:=0;hours_value numeric;rate_value numeric;quantity_value numeric;inventory_item_id uuid;unit_cost_value numeric;
begin
 if actor is null or not private.job_orders_module_enabled(requested_organization_id)or not private.can_business_permission(requested_organization_id,'job-orders.manage',requested_branch_id)then raise exception'Permission denied.'using errcode='42501';end if;
 if requested_priority not in('low','normal','high','urgent')or char_length(btrim(requested_service_type))not between 1 and 160 or char_length(btrim(requested_description))not between 1 and 4000 or char_length(coalesce(requested_notes,''))>4000 or(requested_due_date is not null and requested_start_date is not null and requested_due_date<requested_start_date)or jsonb_typeof(requested_labor_items)<>'array'or jsonb_array_length(requested_labor_items)>200 or jsonb_typeof(requested_material_items)<>'array'or jsonb_array_length(requested_material_items)>200 or not exists(select 1 from public.branches where id=requested_branch_id and organization_id=requested_organization_id and is_active)or not exists(select 1 from public.sales_customers where id=requested_customer_id and organization_id=requested_organization_id)or(requested_staff_id is not null and not exists(select 1 from public.job_order_staff where id=requested_staff_id and organization_id=requested_organization_id and status='active'))or(requested_service_id is not null and not exists(select 1 from public.products where id=requested_service_id and organization_id=requested_organization_id and product_type='service'and status='active'))then raise exception'Invalid job order.'using errcode='22023';end if;
 number:=private.next_job_number(requested_organization_id);insert into public.job_orders(id,organization_id,branch_id,job_number,customer_id,assigned_staff_id,service_id,service_type,description,priority,start_date,due_date,notes,created_by,updated_by)values(target_id,requested_organization_id,requested_branch_id,number,requested_customer_id,requested_staff_id,requested_service_id,btrim(requested_service_type),btrim(requested_description),requested_priority,requested_start_date,requested_due_date,nullif(btrim(requested_notes),''),actor,actor);
 for item in select value from jsonb_array_elements(requested_labor_items)loop if item-array['description','hours','hourlyRate']::text[]<>'{}'::jsonb or not(item?&array['description','hours','hourlyRate'])then raise exception'Invalid labor item.'using errcode='22023';end if;hours_value:=(item->>'hours')::numeric;rate_value:=(item->>'hourlyRate')::numeric;if hours_value<=0 or rate_value<0 or char_length(btrim(item->>'description'))not between 1 and 500 then raise exception'Invalid labor item.'using errcode='22023';end if;insert into public.job_order_labor_items(organization_id,job_order_id,description,hours,hourly_rate,amount,position)values(requested_organization_id,target_id,btrim(item->>'description'),hours_value,rate_value,round(hours_value*rate_value,4),position_value);labor_sum:=labor_sum+hours_value*rate_value;position_value:=position_value+1;end loop;
 position_value:=0;for item in select value from jsonb_array_elements(requested_material_items)loop if item-array['productVariantId','inventoryLocationId','description','quantity']::text[]<>'{}'::jsonb or not(item?&array['productVariantId','inventoryLocationId','description','quantity'])then raise exception'Invalid material item.'using errcode='22023';end if;quantity_value:=(item->>'quantity')::numeric;if quantity_value<=0 or not exists(select 1 from public.inventory_locations where id=(item->>'inventoryLocationId')::uuid and organization_id=requested_organization_id and branch_id=requested_branch_id and is_active)or not exists(select 1 from public.product_variants variant join public.products product on product.id=variant.product_id and product.organization_id=variant.organization_id where variant.id=(item->>'productVariantId')::uuid and variant.organization_id=requested_organization_id and product.product_type='product'and variant.status='active')then raise exception'Invalid material item.'using errcode='22023';end if;insert into public.inventory_items(organization_id,product_variant_id,is_tracked)values(requested_organization_id,(item->>'productVariantId')::uuid,true)on conflict(organization_id,product_variant_id)do nothing;select inventory.id,coalesce(balance.average_unit_cost,variant.cost_price,product.cost_price)into inventory_item_id,unit_cost_value from public.inventory_items inventory join public.product_variants variant on variant.id=inventory.product_variant_id join public.products product on product.id=variant.product_id left join public.stock_balances balance on balance.organization_id=inventory.organization_id and balance.inventory_item_id=inventory.id and balance.location_id=(item->>'inventoryLocationId')::uuid where inventory.organization_id=requested_organization_id and inventory.product_variant_id=(item->>'productVariantId')::uuid;if inventory_item_id is null then raise exception'Material inventory is unavailable.'using errcode='P0001';end if;insert into public.job_order_material_items(organization_id,job_order_id,product_variant_id,inventory_item_id,inventory_location_id,description,planned_quantity,unit_cost,amount,position)values(requested_organization_id,target_id,(item->>'productVariantId')::uuid,inventory_item_id,(item->>'inventoryLocationId')::uuid,btrim(item->>'description'),quantity_value,unit_cost_value,round(quantity_value*unit_cost_value,4),position_value);material_sum:=material_sum+quantity_value*unit_cost_value;position_value:=position_value+1;end loop;
 update public.job_orders set labor_total=round(labor_sum,4),material_total=round(material_sum,4)where id=target_id;insert into public.job_order_audit_history(organization_id,job_order_id,event,to_status,actor_id,details)values(requested_organization_id,target_id,'created','new',actor,jsonb_build_object('laborTotal',labor_sum,'materialTotal',material_sum));return target_id;
exception when invalid_text_representation or numeric_value_out_of_range then raise exception'Invalid job order data.'using errcode='22023';end;$$;

create function private.consume_job_order_materials(requested_organization_id uuid,requested_job_order_id uuid,requested_actor uuid)returns void language plpgsql security definer set search_path='' as $$declare job public.job_orders%rowtype;line public.job_order_material_items%rowtype;remaining numeric;config jsonb;begin select*into job from public.job_orders where id=requested_job_order_id and organization_id=requested_organization_id for update;if job.id is null or job.status in('new','released','cancelled')then raise exception'Job materials cannot be consumed in this status.'using errcode='P0001';end if;config:=private.job_order_config(requested_organization_id);if not coalesce((config->>'consume_inventory')::boolean,true)then raise exception'Inventory consumption is disabled for Job Orders.'using errcode='P0001';end if;for line in select*from public.job_order_material_items where job_order_id=job.id order by inventory_item_id,inventory_location_id for update loop remaining:=line.planned_quantity-line.consumed_quantity;if remaining>0 then perform private.post_stock_movement(requested_organization_id,line.inventory_item_id,line.inventory_location_id,'sale',-remaining,line.unit_cost,null,null,'job_order',job.id,'Consumed for '||job.job_number,'job-order:'||job.id||':material:'||line.id,requested_actor);update public.job_order_material_items set consumed_quantity=planned_quantity where id=line.id;end if;end loop;insert into public.job_order_audit_history(organization_id,job_order_id,event,from_status,to_status,actor_id,details)values(requested_organization_id,job.id,'materials_consumed',job.status,job.status,requested_actor,jsonb_build_object('materialCount',(select count(*)from public.job_order_material_items where job_order_id=job.id)));end;$$;
create function private.consume_job_order_materials_api(requested_organization_id uuid,requested_job_order_id uuid)returns void language plpgsql security definer set search_path='' as $$declare actor uuid:=(select auth.uid());branch uuid;begin select branch_id into branch from public.job_orders where id=requested_job_order_id and organization_id=requested_organization_id;if actor is null or not private.can_business_permission(requested_organization_id,'job-orders.materials',branch)then raise exception'Permission denied.'using errcode='42501';end if;perform private.consume_job_order_materials(requested_organization_id,requested_job_order_id,actor);end;$$;
create function private.change_job_order_status(requested_organization_id uuid,requested_job_order_id uuid,requested_status text,requested_notes text)returns void language plpgsql security definer set search_path='' as $$declare actor uuid:=(select auth.uid());job public.job_orders%rowtype;allowed boolean:=false;config jsonb;trigger_value text;begin select*into job from public.job_orders where id=requested_job_order_id and organization_id=requested_organization_id for update;if actor is null or job.id is null or not private.job_orders_module_enabled(requested_organization_id)or not private.can_business_permission(requested_organization_id,'job-orders.status',job.branch_id)then raise exception'Permission denied.'using errcode='42501';end if;allowed:=case job.status when'new'then requested_status in('accepted','cancelled')when'accepted'then requested_status in('in_progress','waiting','cancelled')when'in_progress'then requested_status in('waiting','completed','cancelled')when'waiting'then requested_status in('in_progress','cancelled')when'completed'then requested_status='released'else false end;if not allowed or char_length(coalesce(requested_notes,''))>2000 then raise exception'Invalid job order status transition.'using errcode='P0001';end if;config:=private.job_order_config(requested_organization_id);trigger_value:=coalesce(config->>'consumption_trigger','manual');if coalesce((config->>'consume_inventory')::boolean,true)and((requested_status='in_progress'and trigger_value='on_start')or(requested_status='completed'and trigger_value='on_complete'))then perform private.consume_job_order_materials(requested_organization_id,job.id,actor);end if;update public.job_orders set status=requested_status,start_date=case when requested_status='accepted'and start_date is null then current_date else start_date end,completed_date=case when requested_status='completed'then current_date else completed_date end,notes=case when nullif(btrim(requested_notes),'')is null then notes else concat_ws(E'\n',notes,btrim(requested_notes))end,updated_by=actor where id=job.id;insert into public.job_order_audit_history(organization_id,job_order_id,event,from_status,to_status,actor_id,details)values(requested_organization_id,job.id,'status_changed',job.status,requested_status,actor,jsonb_build_object('notes',coalesce(requested_notes,'')));end;$$;

create function private.attach_job_order_file(requested_organization_id uuid,requested_job_order_id uuid,requested_path text,requested_file_name text,requested_mime_type text,requested_size bigint)returns uuid language plpgsql security definer set search_path='' as $$declare actor uuid:=(select auth.uid());job public.job_orders%rowtype;target_id uuid;begin select*into job from public.job_orders where id=requested_job_order_id and organization_id=requested_organization_id;if actor is null or job.id is null or not private.can_business_permission(requested_organization_id,'job-orders.manage',job.branch_id)then raise exception'Permission denied.'using errcode='42501';end if;if requested_path not like requested_organization_id||'/'||requested_job_order_id||'/%'or char_length(requested_file_name)not between 1 and 255 or requested_mime_type not in('image/jpeg','image/png','image/webp','application/pdf')or requested_size not between 1 and 10485760 then raise exception'Invalid attachment.'using errcode='22023';end if;insert into public.job_order_attachments(organization_id,job_order_id,path,file_name,mime_type,size_bytes,uploaded_by)values(requested_organization_id,job.id,requested_path,requested_file_name,requested_mime_type,requested_size,actor)returning id into target_id;insert into public.job_order_audit_history(organization_id,job_order_id,event,from_status,to_status,actor_id,details)values(requested_organization_id,job.id,'attachment_added',job.status,job.status,actor,jsonb_build_object('attachmentId',target_id,'fileName',requested_file_name));return target_id;end;$$;
create function private.can_access_job_order_file(requested_path text,requested_permission text)returns boolean language plpgsql stable security definer set search_path='' as $$declare organization_value uuid;job_value uuid;branch_value uuid;begin organization_value:=split_part(requested_path,'/',1)::uuid;job_value:=split_part(requested_path,'/',2)::uuid;select branch_id into branch_value from public.job_orders where id=job_value and organization_id=organization_value;return branch_value is not null and private.job_orders_module_enabled(organization_value)and private.can_business_permission(organization_value,requested_permission,branch_value);exception when invalid_text_representation then return false;end;$$;

create function public.save_job_order(requested_organization_id uuid,requested_branch_id uuid,requested_customer_id uuid,requested_staff_id uuid,requested_service_id uuid,requested_service_type text,requested_description text,requested_priority text,requested_start_date date,requested_due_date date,requested_notes text,requested_labor_items jsonb,requested_material_items jsonb)returns uuid language sql security definer set search_path='' as $$select private.save_job_order(requested_organization_id,requested_branch_id,requested_customer_id,requested_staff_id,requested_service_id,requested_service_type,requested_description,requested_priority,requested_start_date,requested_due_date,requested_notes,requested_labor_items,requested_material_items);$$;
create function public.change_job_order_status(requested_organization_id uuid,requested_job_order_id uuid,requested_status text,requested_notes text)returns void language sql security definer set search_path='' as $$select private.change_job_order_status(requested_organization_id,requested_job_order_id,requested_status,requested_notes);$$;
create function public.consume_job_order_materials(requested_organization_id uuid,requested_job_order_id uuid)returns void language sql security definer set search_path='' as $$select private.consume_job_order_materials_api(requested_organization_id,requested_job_order_id);$$;
create function public.attach_job_order_file(requested_organization_id uuid,requested_job_order_id uuid,requested_path text,requested_file_name text,requested_mime_type text,requested_size bigint)returns uuid language sql security definer set search_path='' as $$select private.attach_job_order_file(requested_organization_id,requested_job_order_id,requested_path,requested_file_name,requested_mime_type,requested_size);$$;

alter table public.job_order_staff enable row level security;alter table public.job_orders enable row level security;alter table public.job_order_labor_items enable row level security;alter table public.job_order_material_items enable row level security;alter table public.job_order_attachments enable row level security;alter table public.job_order_audit_history enable row level security;
create policy job_order_staff_read on public.job_order_staff for select to authenticated using((select private.job_orders_module_enabled(organization_id))and private.can_business_permission(organization_id,'job-orders.read',null));create policy job_orders_read on public.job_orders for select to authenticated using((select private.job_orders_module_enabled(organization_id))and private.can_business_permission(organization_id,'job-orders.read',branch_id));create policy job_labor_read on public.job_order_labor_items for select to authenticated using(private.can_read_job_order(organization_id,job_order_id));create policy job_material_read on public.job_order_material_items for select to authenticated using(private.can_read_job_order(organization_id,job_order_id));create policy job_attachments_read on public.job_order_attachments for select to authenticated using(private.can_read_job_order(organization_id,job_order_id));create policy job_audit_read on public.job_order_audit_history for select to authenticated using(private.can_read_job_order(organization_id,job_order_id));
revoke all on table public.job_order_staff,public.job_order_counters,public.job_orders,public.job_order_labor_items,public.job_order_material_items,public.job_order_attachments,public.job_order_audit_history from public,anon,authenticated;grant select on table public.job_order_staff,public.job_orders,public.job_order_labor_items,public.job_order_material_items,public.job_order_attachments,public.job_order_audit_history to authenticated;
revoke all on function private.install_job_order_permissions(uuid),private.handle_main_branch_job_order_permissions(),private.sync_job_order_staff_membership(),private.job_orders_module_enabled(uuid),private.job_order_config(uuid),private.next_job_number(uuid),private.can_read_job_order(uuid,uuid),private.save_job_order(uuid,uuid,uuid,uuid,uuid,text,text,text,date,date,text,jsonb,jsonb),private.consume_job_order_materials(uuid,uuid,uuid),private.consume_job_order_materials_api(uuid,uuid),private.change_job_order_status(uuid,uuid,text,text),private.attach_job_order_file(uuid,uuid,text,text,text,bigint),private.can_access_job_order_file(text,text)from public,anon,authenticated;grant execute on function private.job_orders_module_enabled(uuid),private.can_read_job_order(uuid,uuid),private.can_access_job_order_file(text,text)to authenticated;
revoke all on function public.save_job_order(uuid,uuid,uuid,uuid,uuid,text,text,text,date,date,text,jsonb,jsonb),public.change_job_order_status(uuid,uuid,text,text),public.consume_job_order_materials(uuid,uuid),public.attach_job_order_file(uuid,uuid,text,text,text,bigint)from public,anon;grant execute on function public.save_job_order(uuid,uuid,uuid,uuid,uuid,text,text,text,date,date,text,jsonb,jsonb),public.change_job_order_status(uuid,uuid,text,text),public.consume_job_order_materials(uuid,uuid),public.attach_job_order_file(uuid,uuid,text,text,text,bigint)to authenticated;
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types)values('job-order-attachments','job-order-attachments',false,10485760,array['image/jpeg','image/png','image/webp','application/pdf'])on conflict(id)do update set public=false,file_size_limit=excluded.file_size_limit,allowed_mime_types=excluded.allowed_mime_types;
create policy job_order_files_select on storage.objects for select to authenticated using(bucket_id='job-order-attachments'and private.can_access_job_order_file(name,'job-orders.read'));create policy job_order_files_insert on storage.objects for insert to authenticated with check(bucket_id='job-order-attachments'and private.can_access_job_order_file(name,'job-orders.manage'));create policy job_order_files_delete on storage.objects for delete to authenticated using(bucket_id='job-order-attachments'and private.can_access_job_order_file(name,'job-orders.manage'));
comment on table public.job_order_material_items is'Planned materials remain non-stock-impacting until configured Job Order consumption posts immutable inventory movements.';
